import type { UserProfile } from '../types';

export const SUN_LECTURES: Record<string, string> = {
  'Aries': `En la relación de pareja eres alegre, fuerte e independiente, eres una persona atrevida y apasionada y te gusta decidir por los dos. Vives en el presente, con entusiasmo, liderazgo, valentía, velocidad y dinamismo. Pero también puedes caer en el egoísmo, la arrogancia, la  impulsividad y el egocentrismo. Puedes ser inconstante, intolerante, impaciente, brusco o demasiado competitiv@.`,
  'Tauro': `En la pareja eres leal, constante y posesiva. Tienes un espíritu artístico, valoras la belleza, el lujo y la sensualidad. Eres confiable, paciente y práctica. Sin embargo, puedes caer en la terquedad, ser argumentativa y necia. Tu posesividad se puede convertir en problema, así como el materialismo y la avaricia.`,
  'Géminis': `Eres sociable, inteligente y divertida, así como también adaptable, curiosa y expresiva. Eres interesante y muy comunicativa. Pero puedes ser cambiante, inconstante o distraída. Te gusta el chisme y la intriga. Cuidado con la mentira, las trampas o la falta de agradecimiento.`,
  'Cáncer': `Eres emotiva, compasiva y doméstica. Tu naturaleza sensible te hace intuitiva, precavida y administrada. A veces ser demasiado emocional te hace ser autocompasiva, hipersensible, sentirte víctima o ser temerosa. Apoyas a quienes amas, pero evita ser sobreprotectora porque puede convertirse en control o manipulación.`,
  'Leo': `Eres romántica, apasionada, cariñosa, te enamoras apasionadamente y lo das todo. Tienes un espíritu generoso, artístico y optimista. Eres digna y segura de ti mismo. Sin embargo, puedes ser vanidosa, orgullosa o dramática. También puedes caer en la arrogancia, el derroche o demasiado dominante.`,
  'Virgo': `Eres detallista, servicial y leal. Tu naturaleza solidaria, prudente y objetiva te hace una excelente pareja, estarás pendiente de todo lo que tu pareja necesite. Pero cuidado de perder la dignidad, ser demasiado fría, criticona o juzgar premeditadamente.`,
  'Libra': `Eres una pareja amable, bella y cooperativa. Eres afectuosa, sociable y armoniosa. Te entregas completamente y buscas compartir todo con tu pareja. Sin embargo, puedes llegar a dejar toda decisión en sus manos, ser demasiado complaciente, quejarte y solo esperar a que él cambie. Tiendes a ser insegura y dependiente de tu pareja. Tienes un espíritu pacifico y artístico pero también puedes ser inconstante o apática.`,
  'Escorpio': `Eres intuitiva, observadora, inteligente y determinada. Sabes obtener lo que deseas. Eres apasionada y sincera. La intensidad de tus emociones te puede hacer temperamental, hiriente e incluso rencorosa. Cuidado con los celos y la lujuria.`,
  'Sagitario': `Eres una pareja alegre, franca y entusiasta. Disfrutas de tu libertad, evitas lo emocional y prefieres abordar la relación con un espíritu filosófico basado en lo que es justo. Eres optimista, naturalmente tienes la vista hacia el futuro y solo te sientes completo cuando la relación tiene un propósito que te emociona. A pesar de tu generosidad, puedes ser imprudente o argumentativo, tus ideales pueden hacer difícil ver la perspectiva de la otra persona. Y puedes tender a la irresponsabilidad, impaciencia o exageración lo que te hace difícil mantener un compromiso a largo plazo.`,
  'Capricornio': `Eres una pareja seria, responsable y tradicional. Valoras lo material, eres práctica y ambiciosa. Puedes aparentar frialdad pero es por tu naturaleza cauta y prudente. Por otro lado, puedes actuar de forma dominante y egoísta. Cuidado también con no ser demasiado negativa, pues tiendes a sobrevalorar el pasado. Si bien es importante guiar tus acciones hacia aquello que te genere admiración, recuerda que no solo vivimos para otras personas y es importante escucharte a ti mismo y a tu pareja.`,
  'Acuario': `Eres inteligente e independiente. Valoras tu libertad e individualidad. Prefieres la lógica sobre las emociones. Tampoco eres la pareja más paciente, puedes ser intolerante si no comparten tu inteligencia. Eres autentica y original pero también puedes ser impredecible, o incluso rebelde. Ante todo, cuida la soberbia. Te es más fácil mantener una relación basada en la amistad, que en el romance.`,
  'Piscis': `Eres intuitiva, emotiva y comprensiva. También soñadora, a veces fantasiosa. Tienes un lado artístico, espiritual, incluso místico. Eres muy romántica y soñadora. También puedes ser muy sensible, volverte pesimista o sentirte incomprendida. Eres distraída, tímida y a veces hasta floja por lo que te costará avanzar la relación por ti misma. Eres caritativa, pero a veces das de más, lo que termina haciéndote sentir como víctima.`
};

export const MOON_LECTURES: Record<string, string> = {
  'Aries': `Buscas alegría, emoción y actividad. No toleras el aburrimiento. Necesitas vivir en el presente y sentirte independiente. Eres emocionalmente fuerte y prefieres la competencia a la dependencia. Puedes ser impulsiv@ y tender al enojo. También caer en el egoísmo, te cuesta trabajo considerar las emociones de tu pareja.`,
  'Tauro': `Buscas lealtad, estabilidad, y comodidad. Tus necesidades emocionales parten de la seguridad y estabilidad financiera. Requieres belleza, lujo y placer para tu estabilidad. No toleras la deslealtad. Eres paciente, pero si se termina reaccionas con enojo. Puedes ser obstinada y argumentativa.`,
  'Géminis': `Tiendes a buscar la diversión, lo interesante y saciar tu curiosidad. Necesitas hablar de tus emociones. También ser sociable y escuchar los chismes e intrigas de los demás. Eres inteligente y adaptable pero ocasionalmente puedes reaccionar con desinterés y evasión. Preferirás utilizar una mentira a tener una confrontación emocional.`,
  'Cáncer': `Eres muy emocional y buscas seguridad y protección. Necesitas tiempo para conectar con tus emociones, en especial en el hogar y rodeada del amor de tu familia. La seguridad financiera también es importante para no sentirte vulnerable. Tus emociones pueden ser demasiado complejas para tu pareja. Tu buena memoria te hace recordar situaciones previas que otras personas olvidan. Es importante que cuides tus cambios de ánimo pues pueden ser abrumadores.`,
  'Leo': `Ante todo buscas el amor, de forma romántica y apasionada. Tu seguridad emocional parte de quien eres y como te ven los demás. Eres orgullosa, y necesitas sentirte amada y admirada por otros. Tu vanidad también requiere verte bien para sentirte bien. Cuidado con ser demasiado explosiva y dramática. Tus relaciones son intensas y puedes ser extenuante para tu pareja. Eres amorosa pero a veces puedes actuar con arrogancia, sentirte superior a tu pareja e incluso actuar cruelmente.`,
  'Virgo': `Buscas el orden, la limpieza y la salud. Eres metódica y objetiva necesitas sentir control para tu estabilidad emocional. El servicio calma tu naturaleza nerviosa, así como el trabajo mental que requiere atención al detalle. Tener un plan ante los imprevistos te hace sentir tranquila. Cuida de no reaccionar emocionalmente con prejuicio e incluso hipocresía. Eres analítica lo que a veces te hace actuar con frialdad y menospreciar las emociones de los demás.`,
  'Libra': `Buscas la paz, armonía y tranquilidad. Tus necesidades emocionales empiezan por los sentidos. Necesitas un entorno que consideres agradable. Tus relaciones son lo más importante y necesitas que sean justas y que puedas depender de ellas. Cuando no encuentras la armonía, tiendes a quejarte. Rara vez resuelves los problemas por ti misma y la soledad es lo que más te afecta.`,
  'Escorpio': `Tienes emociones intensas y profundas. Eres intuitiva, sabes lo que otras personas sienten y piensan. Pero eres reservada con tus emociones y puedes guardar rencores. Cuidado porque a quien más le afecta es a ti. Necesitas tiempo de soledad, para recuperar tu fortaleza y aclarar tus pensamientos. Atraes lo que deseas, pero si tus deseos no son puros te puede traer problemas. En especial si tu temperamento y celos se vuelven autodestructivos. Pero es justo ante la dificultad que encuentras la fuerza interna para renacer.`,
  'Sagitario': `Tus emociones predominantes son la alegría, optimismo y libertad. No te gusta sentirte atrapada, necesitas espacio, tiempo al aire libre y metas que te entusiasmes para sentirte emocionalmente satisfecha. A veces eres imprudente, en especial si tu pareja es muy sensible. Puedes exagerar las situaciones, y prefieres evitar hablar sobre tus emociones, a veces utilizando el sarcasmo. En lugar de eso, abordas la vida con un espíritu filosófico basado en tus ideales. Tus emociones dependen más del futuro que del presente.`,
  'Capricornio': `No eres muy emocional. Tiendes a ser cauta, seria e incluso fría. Para ti la seguridad material es más importante. Tu reputación es también muy importante, te esfuerzas por ser bien vista y causar admiración. Encuentras tranquilidad en lo convencional, no te gusta experimentar nuevas cosas, y prefieres aquello que es práctico. Ante las dificultades, puedes reaccionar con negatividad. Tu ambición también te puede hacer actuar con egoísmo y utilizar a las personas para el cumplimiento de tus objetivos.`,
  'Acuario': `Tus emociones las abordas desde la lógica, no desde el corazón. Incluso te pueden resultar incómodas, sobre todo cuando otras personas las demuestran profusamente. Puedes incluso actuar con intolerancia y frialdad ante genuinas muestras de vulnerabilidad de tu pareja. Eso no significa que no tengas necesidades emocionales, tu libertad es lo más importante. Si te sientes atrapada o no puedes ser tú misma es cuando más temperamental te vuelves. También es importante el estímulo intelectual y ser reconocida por lo que sabes. Solo cuida no actuar con soberbia.`,
  'Piscis': `Vives tus emociones a flor de piel. Eres muy sensible e intuitiva. Pero si no tienes cuidado puedes caer en la tristeza. Eres soñadora, pero cuida de no ilusionarte demasiado. Necesitas desarrollar fortaleza emocional o terminarás sintiéndote como víctima. En lugar de abrumarte enfócate en desarrollar tu intuición, será tu mejor guía para navegar un mundo lleno de sorpresas, y bendiciones. También asegúrate de desarrollar tu fe, te dará fuerza para enfrentar y equilibrar tu predisposición a la negatividad. A pesar de tu emocionalidad, puedes actuar con timidez y reprimir tus emociones con tu pareja. Procura no hacerlo pues solo te hará sentir mas incomhendida. Mejor compártele tu ilusión y sueños y quien sabe, tal vez se pueden hacer realidad.`
};

export const VENUS_LECTURES: Record<string, string> = {
  'Aries': `Tu felicidad radica en la actividad, emoción e independencia. Expresas cariño con alegría y de forma rápida e impulsiva. Tu amor nace de la competencia, necesitas admirar la fortaleza e independencia de tu pareja. Tu inestabilidad y necesidad de libertad puede afectar la relación. Tu independencia puede hacer sentir a tu pareja sola, que no puede depender de ti o que eres egoísta. Tu pareja ideal será aquella que sea fuerte, valiente e independiente con la que pueda divertirte y realizar actividades variadas.`,
  'Tauro': `Tu felicidad está en el lujo, la belleza y el placer. Expresas cariño con sensualidad. La lealtad y fidelidad es lo más importante en tu relación. Pero en exceso se puede convertir en celos y posesividad. Tu relación también puede ser afectada si actúas con necedad o pasividad. Pero en general, eres confiable, paciente y hogareña. Tu pareja favorita ideal aquella persona fuerte, firme y tranquila, que tenga buenos valores y en la que puedas confiar.`,
  'Géminis': `Tu felicidad está en las relaciones sociales, lo interesante, y la inteligencia. Expresas cariño de forma divertida e inventiva. Puedes decir cosas muy bonitas y sentir genuina curiosidad por tu pareja. Necesitas admirar su inteligencia. Puedes ser muy cambiante y la mentira es lo que mas afecta tu relación. Buena comunicación es esencial en tu relación. Tu inquietud puede causar malentendidos. Tu pareja ideal será aquellas persona inteligente, interesante y divertida con la que puedas conversar, pasear y socializar.`,
  'Cáncer': `Venus en Cáncer disfruta del hogar, la familia y la comida. Tiendes a la timidez y prefieres expresar el amor en lo privado, que en público. Buscas dar y recibir protección. La seguridad financiera es importante en tu relación. Habrá veces que sientas mucho amor y otras poco. Puedes apegarte de mucho al pasado y ser demasiado tradicional o conservadora.Tu personas favoritas serán aquellas que sean sensibles, hogareñas y con grandes valores familiares con quien sientas seguridad, cariño y contención.`,
  'Leo': `Para ti la felicidad está en el amor, el romance y la pasión. Lo material es importante y expresas tu cariño con grandes gestos románticos. Tienes magnetismo y puedes despertar envidia en otros, ser deseada es una forma de hacer sentir orgullo a tu pareja. Sin embargo, eres sorprendentemente honesta y fiel: tu pareja puede confiar en ti. Puedes tener expectativas demasiado altas para tu pareja. Exiges ser el centro de atención y puedes actuar de forma dramática y poco comprensiva. Tu orgullo es delicado, aparentas seguridad pero te sientes herida fácilmente.Tu pareja ideal serán aquellas que tenga belleza y porte, que te admire, te haga brillar, te complazca en todo pero que tenga seguridad en sí misma.`,
  'Virgo': `Tu felicidad esta en el orden, la limpieza y la salud. Demuestras amor con los detalles. Eres entregada, solidaria y servicial. No eres emocionalmente muy expresiva pero le demuestras a tu pareja tu amor con tu lealtad. A veces eres fría y el contacto físico te incomoda. La limpieza es importante, tanto en ti como en tu pareja. Puedes ser quisquillosa y darle demasiada importancia a cosas pequeñas. También ser demasiado crítica con tu pareja, es importante que actúes con objetividad y evitar la hipocresía. Tu pareja ideal será aquella que se fije en los detalles, que sea ordenado and saludable, que tome en cuenta lo que es importante para ti, te ayude y te apoye de manera natural.`,
  'Libra': `Tu felicidad está en tu relación de pareja, la armonía y cooperación. Expresas tu cariño afectuosamente. Eres persuasiva y buscas soluciones que sean justas y armoniosas. Eres refinada, buscas la belleza, el arte y la creatividad. Tu mayor problema es la dependencia. Tiendes a la inconstancia e inseguridad lo que hace difícil encontrar balance si tu pareja no es fuerte y confiable. Eres sociable y agradable pero si las cosas no salen como quieres puedes ser quejumbrosa, inconstante o incluso floja. Te es difícil resolver problemas por ti misma. Tu pareja ideal será aquella que sea fuerte y te de seguridad, que te tome en cuenta para prácticamente todo, que sea cariñoso, amable y detallista.`,
  'Escorpio': `Tu felicidad se centra en el cumplimiento de tus deseos. Buscas la intensidad emocional, aun si viene acompañada de celos y emociones tóxicas. Demuestras tu amor con sensualidad, a veces en exceso. Eres inteligente, observadora e intuitiva conoces a tu pareja con profundidad, incluso más de lo que es se conoce el mismo. Sin embargo, te puede hacer controladora, manipuladora y actuar con arrogancia. La intensidad de tu amor llega a causar inestabilidad en la pareja. Cuando todo está bien las cosas son maravillosas, pero cuando no, pueden ser incluso peligrosas. Por tu bien, procura no guardar rencores y ser vengativa. Mejor enfoca tu poder de atracción en buenas intenciones. Tu pareja ideal será aquella persona apasionada e inteligente, que tenga carácter y buenos valores, que sepa lo que quiere y lo consiga, que sea sincera y no se deje engañar.`,
  'Sagitario': `Tu felicidad esta en tu libertad, los viajes o actividades al aire y lo brillante que pueda parecer el futuro. Expresas tu cariño con alegría y generosidad, pero rara vez de forma emocional. Por tu naturaleza optimista tiendes a tomar riesgos, disfrutas de lo emocionante y puede ser difícil para tu pareja compartir tu amor al riesgo, y cuando no seas muy responsable, le puede ser difícil saber que puede confiar en ti. Tu constante búsqueda de libertad puede crear distanciamiento. Cuidado con ser demasiado argumentativa, o evadir situaciones difíciles con sarcasmo. Eres una persona divertida pero también hay momentos que hay que tomar las cosas con seriedad. Tu pareja ideal será aquella que sle guste la aventura, viajar y divertirse, que te haga sentir libre y que sea muy dinámico e independiente, que sea inteligente y desee convertirse en una persona más sabia.`,
  'Capricornio': `Tu felicidad está centrada en el éxito y la admiración de los demás. No expresas tu amor efusivamente, en lugar de eso eres alguien responsable, que disfruta de proveer y causar que tu pareja sienta orgullo de quien eres. Puedes ser perfeccionista, y enfocarte en lo material. Para tu pareja puede ser difícil no poder alcanzar un vínculo emocional. Tiendes a guiarte por lo tradicional, y tu relación se basará más en lo que piensen otras personas que en tus emociones. Para tu pareja también puede ser difícil adaptarse a tu pragmatismo e incluso egoísmo. Tienes metas muy claras y en ocasiones las priorizas sobre tu relación de pareja. Cuidado con ser demasiado negativa, recuerda que la vida también es para disfrutar.`,
  'Acuario': `Tu felicidad está en la amistad, libertad y sabiduría. No toleras la ignorancia. Demuestras tu cariño a tu pareja como si fueran amigos: respetando su espacio, escuchando sin juzgar y sin caer en excesiva emocionalidad. Tu pareja no es alguien convencional. Admiras su originalidad, e incluso excentricidad. Te gusta porque te permite ser tu misma y respeta tu libertad. Eres rebelde y no encuentras la felicidad dependiendo de otra persona. Admiras la inteligencia y amas ante todo la sabiduría de tu pareja. A pesar de tu frialdad, tienes un espíritu humano y altruista. Das sin esperar recibir nada a cambio. Tu pareja ideal será aquella que sea inteligente e interesante, con quien sientas confianza y libertad, que puedas expresarte de forma sincera y auténtica y que comprenda y respete la importancia que tienen tus amistades.`,
  'Piscis': `Tu felicidad está en transmitir y alcanzar tus sueños. Si logras superar tus miedos y melancolía vivirás una vida mágica, llena de misterio y emotiva. Eres tímida al expresar tu amor, pero cuando lo haces te entregas por completo. Eres sensible, tus emociones son tan complejas que pueden ser difícil para tu pareja entenderlas. También eres intuitiva, tu pareja no te puede esconder las cosas. Tus fantasías pueden hacer que te engañes a ti misma. La música es indispensable para sanar tu alma. Vívela y disfruta al máximo. Trata de perseguir el arte, aun algo simple como el dibujo, te servirá para expresarte y sentirte comprendida. Ante todo, busca y ama a Dios, tal como tu espiritualidad te lo permita. Solo en místico encontrarás el consuelo que en este mundo no encuentras. Tu pareja ideal será aquella que sea cariñoso y atento, que te trate con delicadeza. Que te de seguridad y contención, que tenga paciencia y, aunque a veces no te comprenda, te respete. Que tenga buen corazón y valores espirituales.`
};

export const CASA_CUATRO_LECTURES: Record<string, string> = {
  'Aries': `Creciste en un hogar dinámico. Había alegría, pero también impulsividad, incluso desenfreno y a veces enojo. Quizá sentías que tus padres priorizaban sus necesidades sobre las tuyas, incluso que actuaban de forma egoísta.  Pero eso te hizo fuerte e independiente, aprender a actuar con valentía y enfocarte en el presente.`,
  'Tauro': `Creciste en un hogar estable y conservador. Es posible que incluso con seguridad económica. Tu niñez fue hogareña y placentera pero posiblemente te fue imposible imponer tu voluntad. Tus padres actuaban tercos y obstinadas y “NO” fue la palabra que mas escuchaste. A pesar de que tal vez no encontraras el cariño que buscabas, aprendiste buenos valores en el hogar.`,
  'Géminis': `Creciste en un hogar cambiante, siempre encontrabas cosas que despertaban tu curiosidad y te parecían interesantes. En tu familia las palabras predominaban sobre las emociones, las relaciones sociales eran muy importantes, y probablemente conociste una gran variedad de personas. Sin embargo, te era difícil saber exactamente que estaba pasando y quizá hayas encontrado mentiras o intrigas que eran evadidas en lugar de ser confrontadas.`,
  'Cáncer': `Viviste una infancia idílica llena de amor, y cariño en el hogar. Quizá a veces demasiado emocional. Había una constante necesidad de protección, tanto emocional como económica. En la familia encontraste compasión y entendimiento pero también manipulación y sobre protección. También fue un hogar impredecible gobernado por la híper sensibilidad. Te sentiste cercana a tu familia extendida incluyendo tíos, primos y abuelos. En el mundo externo, nunca encontraste la protección que gozabas en casa.`,
  'Leo': `Creciste en un hogar lleno de amor, cariño pero también drama. Eras el centro de atención y la vida familiar girara alrededor de ti. Se esforzaban por mantener las apariencias, quizá había un sentimiento de superioridad que te hacía sentirte mejor que los demás. Pudiste sentir inestabilidad económica, no por carencia sino por mantener un sentimiento de dignidad y en ocasiones lujo y despilfarro. Aún si la familia no era perfecta, había un genuino sentimiento de amor y calidez, quizá disfrutarán de organizar juegos en familia y en general obtenías lo que querías, aún si nunca era suficiente.`,
  'Virgo': `Creciste en un hogar limpio, sano y ordenado. Jamás disfrutaron de grandes lujos pero las cosas funcionan y no había el drama que en otras familias. A veces sentías el hogar frío, no había grandes muestras de cariño y las emociones tendían a reprimirse. Es posible que se viviera un constante sentimiento de preocupación, incluso ansiedad. Predominaba la rutina y todas las actividades giraban alrededor de un plan. Pocas veces había sorpresas, y rara vez sentiste libertad. Al contrario, te sentías controlada y conforme creciste te toco librarte de los prejuicios familiares.`,
  'Libra': `Creciste en un hogar armonioso. Había afecto, y se evitaban los conflictos. Pero también reinaba la pasividad, la cooperación se tornaba en complacencia, la indecisión en dependencia, la complacencia en inconstancia y los problemas se convertían en quejas en lugar de buscar soluciones. Aprendiste buenos modales, a ser sociable y a apreciar la belleza pero siempre te preguntaste porque no había más. Conforme creciste quizá consideraste los ideales de tu familia demasiado “buenos” y en la vida hay que aprender a valerse por uno mismo, aun si eso implica ser un poco más competitivos.`,
  'Escorpio': `Creciste en un hogar intenso. Las emociones fuertes y profundas reinaban. Inesperadamente las cosas podían cambiar de un día a otro, y te tocó experimentar distintos periodos de cambios muy profundos. Jamás gozaste de estabilidad lo que te forzó a ser observadora y desarrollar intuiciones. A pesar del tempestuoso ambiente en el que se vivía, rara vez se hablaba de las emociones y los secretos abundaban. Con el tiempo aprendiste a disfrutar de la soledad, pero es posible que todavía mantengas algún rencor por lo ocurrido en el pasado.`,
  'Sagitario': `Creciste en un hogar alegre. El optimismo reinaba, a veces incluso de forma irresponsable. El entusiasmo y la búsqueda de libertad pudieron hacer que no siempre tuvieras lo que necesitabas. Tampoco había mucha emocionalidad. Al contrario, realizaban actividades al aire libre, incluso viajes, en donde la convivencia nunca adoptaba un carácter personal. Aún cuando existía cierto desdén por la materialidad, adquiriste ideales que pintaron como percibías la realidad, esto pudo ser a través de la religión, política, filosofía o alguna influencia extranjera. La lección mas valiosa que aprendiste fue a hacer motivadas por un propósito, un ideal o visión. Y a hacerlas con alegría.`,
  'Capricornio': `Creciste en un hogar serio, convencional y materialista. Había expectativas altas  y se valoraba la responsabilidad sobre las emociones. Posiblemente tuviste que trabajar y colaborar desde temprana edad y reprimir tus emociones. La satisfacción provenía del exterior, de lo que pensaban los demás y de su admiración. Las ambición es lo que movía la familia hacia delante, siempre buscando superarse a base del trabajo. Sin embargo, aun cuando se logran los objetivos, se podia sentir una atmósfera de melancolía, pocas veces se celebraban los éxitos, y nunca era suficiente.`,
  'Acuario': `Creciste en un hogar diferente, único y original. Las emociones, y el materialismo eran menos importantes que las ideas y la inteligencia. No les importaba mucho lo que la sociedad pensara, e inculcaron en ti un sentimiento de individualidad, quizá al grado de ser excéntricos. Había un sentimiento de soberbia o rebeldía, de que otras personas estaban equivocadas y ustedes tenían la razón. Quizá hubo ausencia de uno o ambos padres, en su lugar te tocó encontrar tu propio camino. Es posible que tu hogar fuera de alguna forma futurista, ya sea que estuvieras más cercana a la tecnología que los demás o que los valores que recibiste fueran adelantas a la época.`,
  'Piscis': `Creciste en un hogar amoroso o caótico. Es posible que no recuerdes mucho o que no entendieras lo que pasaba. Había emociones, sueños e incluso espiritualidad pero también fantasía, pesimismo y timidez. La vida en el hogar se sentía muy diferente a fuera del hogar, incluso les podía costar adaptarse. Puede ser que fueran demasiado “buenos” y la realidad más distinta, dolorosa. Si bien había mucho amor, eso no se convertía en materialidad, y cuando había problemas el ambiente se tornaba en melancolía en lugar de buscar soluciones. Es posible que experimentaras algunos “milagros” que cuando parecía que no había solución, mágicamente las cosas se arreglaban. Desarrollaste intuición, y hay sentimientos muy profundos que tal vez no hayas terminado de explorar. La sanación inicia desde la aceptación.`
};

export const DESCENDENTE_LECTURES: Record<string, string> = {
  'Aries': `Tiendes a ser complaciente, afectuosa y sociable. Pero para que tu relación funcione requieres ser mas independiente, valiente e impulsiva. En lugar de buscar persuadir, ser asertiva y expresar lo que quieres. Si por el contrario, caes en la inseguridad, dependencia y conformismo tu pareja se tornará egoísta, egocéntrica e incluso brusca, aprovechando tu debilidad, no por maldad sino como la inocencia de un niño que solo busca recibir. Evita la indecisión, viviendo más en el presente, acepta la competencia en lugar de la sola cooperación, y reemplaza las quejas con seguridad en ti misma. Infunde tu relación con alegría en lugar de intriga.`,
  'Tauro': `Normalmente eres una mujer apasionada, emocional e intuitiva. Sin embargo, para que tu relación funcione necesitas aprender a ser más estable, a buscar menos el cambio y a valorar más la comodidad y el confort. Estás acostumbrada a realizar grandes cambios para renacer y fortalecerte, pero el éxito de tu relación está centrada en la estabilidad de tus valores. Te tocará defender tus valores, aún si eso se convierte en necedad y terquedad. Aprenderás a encontrar el deseo y pasión más allá de la intensidad de las emociones en el valor de las posesiones materiales, que proveen comodidad, seguridad y placer. Aprenderás a apreciar los lujos e incluso a desarrollar una apreciación artística. Si en cambio, utilizas tu intuición para controlar a tu pareja, los celos, la posesividad, materialismo, obstinación e incluso ira aparecen en tu relación.`,
  'Géminis': `Normalmente eres una mujer franca, entusiasta, en búsqueda de la libertad. Sin embargo, para que tu relación funcione deberás aprender a ser más versátil, a adaptarte a las circunstancias y a encontrar goce en la cotidianidad de las relaciones sociales y no solo en tu incansable búsqueda de libertad. Estás acostumbrada a “conocer la verdad” pero cuando tu pareja, tiene una opinión diferente puedes actuar argumentativa, dogmática, e incluso brusca e inconsiderada. En su lugar en la relación aprenderás a actuar con más curiosidad, a matizar tus opiniones: no todo es blanco o gris, bueno o malo. A cultivar nuevos intereses, y a encontrar felicidad en las interacciones “superficiales” o “insignificantes” y no solo persiguiendo las grandes aspiraciones. Aprenderás el valor de la dualidad, de que lo bueno, o verdadero depende de las circunstancias. Aprenderás que la verdad cuando es directa y con franqueza puede ser desconsiderada e incluso brusca o agresiva. Y aprenderás que solo experimentando la polaridad es que uno alcanza la verdad absoluta.`,
  'Cáncer': `Normalmente, eres una mujer responsable pero también fría y preocupada por el mundo material. Sin embargo, para que tu relación funcione, deberás demostrar tus emociones y vulnerabilidad. A abrirte a tu pareja y actuar comprensiva y compasiva ante sus debilidades. Aprender a valorar la comodidad del hogar, en lugar del prestigio del mundo exterior. A priorizar los sentimientos de tu pareja sobre lo que los otros puedan pensar. E incluso actuar con irresponsabilidad para satisfacer necesidades emocionales. En lugar de siempre aspirar a mas, y perseguir objetivos materiales, encontrarás mayor satisfacción en el calor del hogar, en el sabor de una comida hogareña, en la compañía de la familia y en compartir las emociones sabiendo que puedes encontrar seguridad y protección en tu pareja y no solo en el mundo material.`,
  'Leo': `Tu relación tiende a ser romántica, cariñosa y dramática. Estás acostumbrada a buscar la libertad, es independiente, y diferente. Sin embargo, en la relación eres cálida, apasionada y entregada. Cuando regresas a tus tendencias intelectuales, de frialdad emocional, rebeldes o incluso soberbia, la relación se torna dramática, pretenciosa, llena de orgullo y arrogancia. Para que la relación mejore, no es necesario cambiar quien eres, solo demostrar mas amor, compartir las emociones, ser mas cariñosa y evitar hacer sentir mal o poco inteligente a tu pareja.`,
  'Virgo': `Tienes la tendencia a ser amorosa, sensible y en ocasiones distraída. Pero para que tu relación funcione deberás aprender a actuar basada en la lógica y no solo en el corazón. Aprenderás la importancia de los detalles, del orden en lugar del caos, y de controlar tus emociones en lugar de caer víctima del pesimismo y negatividad. Aprenderás a dejar atrás los sueños y fantasías, y a aceptar con practicidad la rutina de la vida diaria. Dejarás atrás comportamientos de exceso o dañinos y cultivarás hábitos que cuiden tu salud. Cuando de lo contrario, actúes de forma muy emocional, fantasiosa o con tristeza tu pareja se volverá fría, analítica y objetiva. En su lugar, cultivarás las virtudes del servicio, la lealtad y orden que le permitirán a tu pareja confiar en ti y saber que puede depender de ti. Balancearás las emociones con la razón, y le darás importancia a esos pequeños detalles que te permiten vivir una vida ordenada y sana en pareja durante un largo tiempo.`,
  'Libra': `Tiende a ser una mujer segura, independiente y fuerte. Pero para que tu relación funcione necesitas aprender a compartir, cooperar, ceder y a ser afectuosa, incluso mostrar vulnerabilidad. Normalmente, actúas de forma impulsiva, priorizando tus necesidades sobre las de los demás. En la relación, el bienestar es lo que encuentras cuando ambos están bien y eso implica la búsqueda de la armonía, el equilibrio y aprender a ser persuasiva en lugar de brusca y directa. Cuando actúas de forma egoísta, tu pareja se torna quejumbrosa, dependiente y débil pero es porque te está enseñando a ser vulnerable y a compartir.`,
  'Escorpio': `Normalmente eres una mujer paciente, conservadora y estable. Sin embargo, para que tu relación funcione deberás ser más apasionada, intensa e intuitiva. Dejar de buscar la comodidad y armonizar la intensa emocionalidad que acompaña tu relación. También significa perder la estabilidad y realizar cambios profundos para que la relación renazca, florezca y continúe. Cuando actúes en extremo materialista, emociones profundas surgirán incluyendo celos y rencores acompañados de palabras hirientes e incluso vengativas. Algo similar ocurrirá cuando actúes con necedad y obstinación, si te resistes al cambio, patrones autodestructivos en la relación surgirán. En su lugar, busca actuar con más inteligencia, ser más observadora y desarrollar la intuición.`,
  'Sagitario': `Normalmente eres una mujer sociable, adaptable y versátil. Estás acostumbrada a ser cambiante y adaptarte a las circunstancias y personas con las que estas hablando. Pero para que tu relación funcione, requieres variedad y actividades distintas, así como encontrar aquella verdad sobre la que tu relación se sostenga. Dejar de hacer las cosas de forma reactiva a las circunstancias y comenzar a hacerlas en pareja siguiendo un propósito. De lo contrario, cuando retornes a la superficialidad del día a día encontrarás chismes, intrigas e incluso mentiras que pondrán tu relación a prueba. Otro aspecto que te toca trabajar en tu relación de pareja es ser más agradecida y buscar actuar con más generosidad. Dejar de buscar la intriga, y comenzar a buscar la verdad. Dejar de actuar con inquietud, víctima de la distracción y el desinterés y compensar a aspirar ese ideal filosófico bajo el cual tu relación avance hacia adelante.`,
  'Capricornio': `Tiendes a ser una mujer emotiva, compasiva y hogareña. Sin embargo, para que tu relación funcione deberás aprender a adquirir responsabilidad, a actuar con practicidad y seriedad. De lo contrario cuando actúes de forma híper sensible tu pareja se tornara negativa, melancólica e incluso dominante. Tu pareja te enseñará a desarrollar ambición, a dejar atrás la comodidad y seguridad del hogar y a encontrar prestigio en el éxito, la admiración de los demas y la consecución de los cosas materiales. En la relación serás menos emocional, mas fría, menos manipuladora y mas responsable. Por ejemplo, en lugar de sentirte como víctima, resolverás los problemas por ti misma. Y en lugar de depender de tu pareja, adquirirás responsabilidades que le permita a tu pareja confiar y apoyarse en ti, para tener una relación duradera, exitosa y admirable.`,
  'Acuario': `Estás acostumbrada a ser una mujer voluntariosa, apasionada y romántica. Pero para que tu relación funcione a largo plazo la necesitas equilibrar con sabiduría, libertad e individualidad. Permitir a tu pareja ser quien es, y no quien quieres que sea. Evitar el dramatismo y resolver los problemas con lógica y frialdad. A dejar atrás tu búsqueda de romance y aprender a amar sin esperar nada a cambio. A desarrollar inteligencia dentro de la relación. Dejar atrás el drama, la ambición y en su lugar desarrollar tu individualidad. Dejar de pretender para los demás y convertirte en quien realmente eres. Incluso a sacrificar el cariño y convertir la relación más en una amistad que en una novela romántica. Por el contrario, cuando actúes de forma apasionada y egocéntrica tu pareja se mostrará fría y rebelde, rechazando tus muestras de cariño y mostrándose intolerante, arrogante y temperamental. Sin dedicarte la atención que estás acostumbrada a recibir.`,
  'Piscis': `Estás acostumbrada a ser una mujer ordenada, objetiva y organizada. Pero para que tu relación funcione deberás abrir paso a las emociones y aprender a expresar amor en lugar de actuar con rigidez y frialdad. Entenderás que en la vida de pareja no todo se puede planear o ser perfecto. Que una relación no solo se basa en lealtad, servicio y practicidad. Es igualmente importante la comprensión, emotividad y sensibilidad. Sustituirás los planes por los sueños. Te atreverás a imaginar un mundo diferente al de la rutina diaria. Y aprenderás a ceder a aquellas cosas aunque no sean las ideales o perfectas. Dejarás atrás el nerviosismo y cultivarás la fe. Es posible que incluso a través de tu pareja encuentres tu camino espiritual. De lo contrario, cuando actúes con frialdad, tu pareja actuará con híper sensibilidad, sentimientos de victimización, negatividad e incluso actitudes de evasión incluyendo el alcohol. Conforme aprendas a actuar con sensibilidad, conectarás con esa timidez y vulnerabilidad de quien se atreve a soñar.`
};

export const PADRE_LECTURES: Record<string, string> = {
  'Aries': `Durante tu infancia, tu padre fue una figura fuerte. Actuaba con independencia, incluso actuando con egoísmo. Te educo con el ejemplo y no siempre te dio la atención o reconocimiento que buscabas. En lugar de atender las necesidades del hogar, tu madre o su pareja actuaba de forma egocéntrica. Sin embargo, admirabas su fuerza y liderazgo, aun cuando nunca cumplieras sus expectativas. Reaccionaba con competitividad en lugar de apoyo. Además, era sumamente impaciente, podía ser impulsivo y actuar con brusquedad e incluso tender al enojo, es posible que le tuvieras miedo.`,
  'Tauro': `Durante tu infancia, tu padre fue una figura confiable y conservadora. Generalmente mas ocupado en el dinero y las posesiones materiales que en ti. Era alguien practico, pero también terco y obstinado, podía actuar con argumentativo y con necedad quizá nunca le hiciste cambiar de opinión. Si insistías, incluso podía actuar con enojo. También era celoso, incluso posesivo, aun cuando valoraba la lealtad por encima de todo quizá nunca sentiste que confiaba en ti del todo.`,
  'Géminis': `Durante tu infancia, tu padre era inteligente, divertido y curioso. Ocasionalmente lo cachabas diciendo alguna mentira, prefería evadir el conflicto e incluso la responsabilidad. Cambiaba de opinión frecuentemente y con velocidad . Fácilmente perdía el interés, y su atención se movía con rapidez. Si bien recuerdas innumerables momentos divertidos jamás supiste quien realmente era. Era sociable y adaptable y daba una cara diferente de acuerdo a las personas y circunstancias que le rodeaban.`,
  'Cáncer': `Durante tu infancia, tu padre fue una figura sensible, compasiva y amorosa. Puede ser que se preocupara demás por la seguridad económica. Disfrutaba much el hogar, pero nunca fue lo responsable que te hubiera gustado. En lugar de actuar de forma directa, con asertividad actuaba con manipulación, y era extremadamente sobre protector. Puede ser que incluso lo consideras miedoso, demasiado precavido. Pero sobre todo, lo amabas y disfrutabas pasar tiempo con él en el hogar.`,
  'Leo': `Durante tu infancia, tu padre fue una persona digna, generosa e idealista. Era seguro y generalmente era el centro de atención. Le gustaba jugar y demostraba cariño. Sin embargo, también podía ser orgulloso y arrogante. Podía ser también clasista, pretensioso e incluso fanfarrón. Su vanidad le llevaba a aparentar e incluso ser en extremo dominante.`,
  'Virgo': `Durante tu infancia, tu padre fue alguien metódico, analítico y servicial. No mostraba grandes muestras de cariño pero te apoyaba en lo que necesitabas. Era ordenado y le gustaba planear las cosas pero podía ser obsesivo y enfocarse demasiado en pequeños detalles. Le gustaba seguir una rutina, pero aun cuando las cosas eran perfectas se mostraba nervioso y con preocupación. Era alguien serio y le importaba más tu educación que los juegos o tus emociones.`,
  'Libra': `Durante tu infancia, tu padre fue una buena persona, era afectuoso y agradable. Amaba a tu madre, o su pareja, quizá demasiado y lo hacia dependiente. No podía tomar decisiones por sí mismo. Y aunque buscaba ser complaciente, la realidad es que se quejaba mas de lo que daba. Sin embargo, fue un padre justo e incluso sabio. Si bien no siempre tomaba accion, daba buenos consejos. Conforme creciste, es posible que se volviera mas una responsabilidad que un apoyo. A pesar de todo, lo amabas.`,
  'Escorpio': `Durante tu infancia, fue una persona sumamente inteligente. Tenía una mirada penetrante, que sabía exactamente lo que estabas pensando. No había forma de guardarle secretos. Admirabas su intuición, pero es posible que fuera demasiado temperamental e incluso le tuvieras miedo. Era sincero, al grado de ser hiriente. Era determinado y lograba lo que deseaba, pero en ocasiones eran sus rencores y no buenas intenciones lo que lo llevaba a situaciones autodestructivas. Era celoso y a pesar de que no comunicara lo que sentía, sabias exactamente lo que pensaba de tus acciones.`,
  'Sagitario': `Durante tu infancia, tu padre fue alguien alegre, si bien irresponsable. Le gustaban las actividades al aire libre, era optimista y generoso. Vivía de acuerdo a ideales elevados, lo que le hacía ser justo. Sin embargo, su búsqueda de la libertad le hacía caer en la irresponsabilidad, incluso imprudencia. De la misma forma, su optimismo se tornaba en riesgo y aun cuando buscara la verdad por encima de todo, sus ideales le podían hacer distorsionar la realidad. Puede ser que fuera un padre ausente, incluso viviendo fuera, o en el extranjero. Aún cuando su carácter alegre dominaba, en ocasiones se podía tornar impaciente, argumentativo y exagerado incluso brusco. Conforme creciste pasaste de la ciega admiración a reconocer con más equilibrio sus cualidades y defectos.`,
  'Capricornio': `Durante tu infancia, tu padre fue una figura responsable, trabajadora y admirada. Es posible que diera una cara a la sociedad, y otra en la familia. Era frío y no demostraba amor. En ocasiones podía ser fatalista, o negativo, incluso cruel, le costaba considerar a los demás, sobre todo sus emociones. No entendía como otros no trabajan como él, o peor aún, ser irresponsables. Tenía grandes ambiciones, y se comportaba como si otros lo observabaran. Era convencional, incluso al grado de reprimirse. Actuaba de forma práctica y calculadora y aunque no era generoso buscaba proveer a la familia con todo lo necesario.`,
  'Acuario': `Durante tu infancia, tu padre fue una persona inteligente. Sabía mucho y rara vez aceptaba no tener la razón. Era alguien original que no le interesaba mucho lo que los demás pensaran. A pesar de eso, tenía un espíritu humanista, buscaba el bien común y basaba sus opiniones en la lógica y la razón. Es posible que aunque no fuera muy emocional si tuviese muchas amistades. Pero sobre todo, es posible que fuese un padre ausente, su atención estaba no estaba en la familia, ni demostraba mucho amor. Pudo ser innovador, tener ideas futuristas o radicales que el tiempo le dio la razón.`,
  'Piscis': `Durante tu infancia, tu padre pudo haber sido una figura amorosa y emotiva pero también evasiva e incluso caótica. Es probable que su emocionalidad lo llevara a sentirse a veces muy inspirado, optimista incluso con fe pero otras veces negativo, pesimista y melancólico. Era alguien en quien podías confiar para sentirte comprendida pero también podía ser despistado y olvidar o evadir las responsabilidades. Conforme creciste, te diste que cuenta que se sentía incomprendido, la vida le causaba sufrimiento y en verdad quería que las cosas fueran diferentes, mas idealistas, mas “buenas” y que las personas mostraran mas compresión y entendimiento.`
};

export const MADRE_LECTURES: Record<string, string> = {
  'Aries': `Tu madre fue una figura (durante tu infancia) independiente. Es muy posible que no hayas sentido que no siempre te dio la atención que necesitabas y priorizaba sus necesidades sobre las tuyas. Era valiente y fuerte, seguramente más segura que tu padre. Aún cuando podía ser brusca o impaciente, te dio un gran ejemplo de una mujer que sabe sobresalir por sí misma. Cuando no estaba molesta, su alegría y entusiasmo eran contagiosos.`,
  'Tauro': `Tu madre fue una figura (durante la infancia) paciente, práctica y hogareña. Es posible que fuera una mujer hermosa. Le gustaba disfrutar del dinero, y los placeres de la vida. Constante buscaba la seguridad, sobre todo material. Puede ser que hayas sentido que amaba más las posesiones materiales. Podía actuar con terquedad, pero tenía buenos valores que te enseño con paciencia y obstinación.`,
  'Géminis': `Tu madre fue una mujer durante tu infancia muy platicadora. Le gustaba conocer gente y le fascinaban los chismes y las intrigas. Quizá nunca te dedico la atención que necesitabas, ni tampoco recibiste grandes muestras de cariño. Aún sin ser muy emocional, era muy cambiante. Nunca sabias exactamente lo que pensaba. Podía decir dos cosas completamente diferentes, dependiendo de con quien platicara y no sentir el mas mínimo remordimiento. Puede ser que sintieras que no fuese agradecida, sobre todo con tu padre.`,
  'Cáncer': `Tu madre fue una mujer durante la infancia, sensible hogareña y amorosa. Podía ser voluble y demasiado emocional pero priorizaba la familia por encima de todo. Era devota, completamente entregada, al grado de a veces sentir que daba todo y no recibía nada a cambio. Era cauta y precavida, puede ser que incluso actuara con negatividad y el miedo la llevara a ser sobreprotectora. También podía ser impredecible y su híper sensibilidad la podía llevar fácilmente al llanto. Era cercana a su familia, seguía las tradiciones y buscaba propiciar un hogar seguro. Pero sobre todo, era inmensamente amorosa.`,
  'Leo': `Tu madre fue, durante tu infancia, una mujer sensacional, admirada y con clase. Era segura, vanidosa y amorosa. Vivía apasionadamente y te hacía sentir especial. En ocasiones podía ser en extremo orgullosa, dramática. También pudo tener altas expectativas de ti, que a pesar del cariño que te tenía nunca pudiste cumplir del todo. También le gustaban los lujos, y gastaba más dinero del que podía. Buscaba el romance y sentirse el centro de atención.`,
  'Virgo': `Tu madre, durante tu infancia, fue una mujer seria, objetiva y controladora. Era limpia y ordenada, a veces incluso quisquillosa. A pesar de que fuera a veces demasiado fría, podías confiar en ella. Era práctica y servicial. Se esforzaba por mantener una rutina y que vivieran una vida saludable. Quizá preocuparse de más por la salud e incluso pudo tener problemas de salud. Creciste controlada por sus prejuicios, y aunque quizá no recibiste de ella el cariño que necesitabas, con el tiempo aprendiste a apreciarla y valorar sus atenciones y detalles.`,
  'Libra': `Tu madre (durante la infancia) fue amable, complaciente y equilibrada. Pero también era indecisa y dependiente de tu padre o su pareja. También podía ser conformista e insegura, se quejaba en lugar de resolver los problemas por sí misma. Pero también era persuasiva, armoniosa y buscaba mantener la paz en el hogar.`,
  'Escorpio': `Tu madre, durante tu infancia, fue una mujer extremadamente intuitiva. Era reservada y no compartía sus emociones pero sabia exactamente lo que estabas pensando. Incluso sabía lo que iba a pasar. Era una mujer poderosa, conseguía lo que buscaba, aparentemente sin esfuerzo. Podía actuar con arrogancia y ocasionalmente actuar extremadamente temperamental, incluso con violencia. Sus palabras herían, y aunque después pudiera sintiera culpa, parecía que en el momento disfrutaba hacer daño era una forma de cobrar venganza y sentir su poder. Con el tiempo quizá preferiste la soledad, y distancia en lugar de buscar el amor materno.`,
  'Sagitario': `Tu madre, durante tu infancia, fue una mujer entusiasta, optimista y alegre. Pero también era impaciente, incluso imprudente. Aunque amabas su compañía no siempre fue la madre más responsable o te dio todo lo que necesitabas. Sin embargo, era una excelente consejera, conforme creciste podías confiar en su sabiduría. Si bien podía ser un poco idealista y optimista, sus consejos estaban basados en la verdad y los ofrecía con generosidad, aun si no los pedías. Tampoco fue la madre más presente, ella buscaba libertad y sentías que la vida familiar la atrapaba. Aún cuando no pudieras compartir tus emociones con profundidad te enseño ideales, propósito y una visión que no encontraste en ningún otro lugar. Hay ocasiones que esa ausencia eran ocasionadas por su religiosidad, y te toco a ti encontrar tus propios valores.`,
  'Capricornio': `Tu madre, durante tu infancia, fue una mujer seria, trabajadora y responsable. No demostraba sus emociones, incluso las reprimía. Le era más importante como la percibían los demás que lo que sintiera. Tampoco demostraba mucho amor, su atención la enfocaba a que fueras responsable, bien portada y convencional: siguiendo lo que la sociedad determinaba como aceptable. Era una mujer ambiciosa, que ponía mucho valor en las cosas materiales. Podía actuar de forma dominante, y conforme creciste pasaste de buscar su amor, a que se sintiera orgullosa de ti.`,
  'Acuario': `Tu madre, durante tu infancia fue una mujer diferente. No era la madre convencional, tenia sus propias ideas, no temía expresarlas y le importaba poco lo que otros pensaran. Incluso había una rebeldía en ella que le gustaban ir en contra de lo tradicional y demostrar que tenía razón. No era la madre mas emotiva o afectuosa, por lo menos tampoco estaba muy presente. Tu relación con ella fue mas como una amiga que como una madre. Te dio mucha libertad. Era una buena persona, se preocupaba genuinamente por otros, y probablemente en especial por los animales y el planeta.`,
  'Piscis': `Tu madre, durante tu infancia, fue una figura amorosa, soñadora y hasta romántica. Tenía un alma sensible y compasiva. En ella podías encontrar entendimiento, pero quizá también híper sensibilidad. Puede ser que se sentiera como víctima, y en lugar de poder depender de ella a veces te sentías responsable por ella. Tenía sensibilidad artística, sobre todo en la música que le ayudaba a calmar sus emociones. Podía ser negativa, miedosa o incluso espiritual, aun sin ser muy religiosa. También podía ser floja, y preferir evitar las responsabilidades que solucionar los problemas.`
};

export const NODO_LUNAR_LECTURES: Record<string, string> = {
  'Aries': `Tiendes a ser egoísta o egocéntrica. En vidas anteriores te acostumbraste a priorizar tus necesidades sobre las demás. En ocasiones, esto es necesario pero en esta vida vienes a aprender a compartir, a reemplazar la impulsividad con refinamiento y sociabilidad. A dejar de buscar la victoria, y encontrar soluciones diplomáticas que satisfagan a todos. A ser amable en lugar de brusca. A reemplazar la valentía con precaución. Y dejar atrás la independencia por la cooperación. A ser menos impaciente, desesperada y a considerar más a los demás en tus decisiones. Tu camino de crecimiento espiritual te lleva a buscar la armonía, la paz y la belleza. De lo contrario la vida te continuará dando lecciones hasta aprenderlo.`,
  'Tauro': `Tienes la tendencia kármica a ser confiable y práctica. A buscar la seguridad en lo material, y a disfrutar del placer y los lujos de la vida. Sin embargo, en esta vida, has venido a desarrollar tu poder interior, a alcanzar el cumplimiento de tus deseos no a partir de cosas materiales sino de tu inteligencia, intuición y poder de atracción. A explorar la intensidad del mundo emocional, y dejar atrás la rigidez y lentitud del mundo material. A dejar de temer el cambio o inestabilidad y aceptar la transformación como camino a la fortaleza personal. A dejar de buscar la practicidad de lo convencional o tradicional y a disfrutar de los momentos de soledad para fortalecer tu poder personal. A dejar atrás la paciencia, terquedad u obstinación y a sumergirte en las profundas emociones del inconsciente que pueden transformar todo de un momento a otro.`,
  'Géminis': `Tienes la tendencia kármica a ser dual, adaptable y cambiante. Pero en esta vida has venido a buscar y encontrar la verdad. Ese ideal, o aspiración que está por encima de la superficialidad de las relaciones sociales, del chisme, de la intriga, de aquello que te parece interesante, o te causa curiosidad. Vienes a perseguir una visión basada en una verdad universal o ideal superior. Este ideal lo puedes encontrar en la espiritualidad o religiosidad, en los viajes o en el extranjero, en la filosofía o incluso en la política. Encontrando una causa que dirija tu propósito y acciones más allá de las interacciones de la vida diaria. Durante el proceso lo mas importante es que aprendas a actuar y expresarte con honestidad, aun si eso implica ser hiriente, entrar en argumentos o causar incomodidad. Todo es parte del camino de la búsqueda de la verdad. Como recompensa encontrarás la libertad y expansividad de saber que podemos aspirar y lograr mas de lo que nuestro alrededor aparenta.`,
  'Cáncer': `Vienes de vidas anteriores en donde has actuado con híper sensibilidad, priorizando las emociones sobre la responsabilidad y dependiendo de tu familia para encontrar protección. En esta vida vienes a desarrollar el trabajo y la responsabilidad. A dejar atrás la emocionalidad y el calor del hogar para alcanzar éxitos en el mundo material. Descubrirás que la seguridad y protección no se encuentra en la vulnerabilidad de las emociones, sino en la durabilidad de las posesiones materiales. En el proceso ganarás la admiración de tu familia y sabrán que pueden depender de ti. Construirás la calidez del hogar que buscas no en base a la compresión y compasión sino a través de responsabilidad y logros materiales. Aprenderás a regular tus emociones, actuar con frialdad y practicidad y a no mostrar vulnerabilidad. Para tu sorpresa encontrarás que disfrutas de la admiración de extraños tanto como de tus seres queridos.`,
  'Leo': `Vienes de vidas anteriores llenas de romance, pasión y vanidad. Te has acostumbrado a seguir ciegamente los mandatos del corazón. En esta vida has venido a desarrollar sabiduría, a aprender a ver las situaciones con frialdad y objetividad y a dominar las pasiones y deseos del corazón. Has perseguido tanto tu bienestar personal, que ahora te toca actuar en base al bien común. Dejar de aspirar a ser el centro de atención y en su lugar convertirte en la sensata voz de la sabiduría, basada en experiencia. Tiendes a actuar basado en lo que otras personas esperan de ti, ahora te toca desarrollar tu individualidad. Ser quien eres aún si esto implica ser diferente o incomprendida y actuar con rebeldía sabiendo que tienes la razón. Tu recompensa será descubrir la libertad. Libérate de las expectativas y pretensiones siendo admirada por tu inteligencia y no por como te ves. Aprenderás a amar incondicionalmente como una amiga y menos como la turbulenta pasión rodeada de drama.`,
  'Virgo': `Tiendes a ser analítica, nerviosa y prudente. En esta vida has pactado explorar más tus emociones y tu intuición, improvisar en lugar de planear y sobre todo tener FE. Si bien eres servicial, leal y solidaria tu forma de servir cambia de lo práctico a lo emocional, ser más compasiva, comprensiva y caritativa. Dar sin buscar algo a cambio, sino a quien más lo necesita. Soltar la necesidad de control y usar mas tu intuición. Y sobre todo, a dejar de centrarte en los pequeños detalles, ser mas expansiva atreverte a soñar y sentir inspiración.`,
  'Libra': `Tiendes a ser complaciente, a priorizar las necesidades de los demás sobre las tuyas. A actuar con indecisión, inseguridad y complacencia. Pero en esta vida, has venido a aprender a ser independiente, a valerte por ti misma y a cultivar fortaleza y seguridad. La vida te empujará a actuar con valentía, incluso impulsividad, a defender lo que es tuyo y a conseguir lo que quieres y necesitas. Lentamente aprenderás a valorar la competencia y a buscar el triunfo, aun si esto implica que otros pierdan, porque ese es el camino para desarrollar la mejor versión de ti.`,
  'Escorpio': `Tiendes a ser una mujer profundamente emocional, a experimentar cambios intensos y manifestar tus deseos a partir de tu poder de atracción. Pero en esta vida has venido a aprender el valor de la estabilidad, paciencia y practicidad. Desarrollarás los valores que darán estabilidad a tu vida, los cuales defenderás con obstinación e incluso necedad. Pasarás del tempestuoso mundo emocional, a valorar la seguridad del mundo material que se alcanza con paciencia, consistencia y practicidad. En el proceso dejarás atrás tendencias autodestructivas basadas en rencores, heridas subconscientes y deseos de venganza. Las remplazarás con el placer del lujo, la apreciación de las cosas materiales y sobre todo la lealtad a aquellas personas en las que puedes confiar para mantener tu estabilidad y riqueza.`,
  'Sagitario': `En vidas pasadas has actuado persiguiendo una “verdad” o “ideal” desconectada de la esfera social. En donde has sido percibida como argumentativa o incluso “salvaje”, lejos de la sociedad y civilización. Pero en esta vida vienes a comunicar, compartir y enseñar la verdad que has encontrado y la que le has dedicado tu búsqueda y viajes. Para ello tendrás que aprender a adaptarte, a cambiar la forma de comunicar tu mensaje o verdad de acuerdo a la audiencia que te escucha. A mostrar curiosidad, y aprender de otros tanto o más como tú les puedas enseñar. Refinar tu mensaje con elocuencia, gracia y curiosidad para que otros se interesen en lo que tienes que decir. Y a dejar de perseguir un único objetivo y dejar que la casualidad de las relaciones diarias guíe tu camino. De lo contrario, la vida te demostrará que la verdad que tanto sostienes y argumentas no siempre es verdadera, es relativa, y requiere de versatilidad, adaptación y gracia para convertirla en realidad.`,
  'Capricornio': `Has venido de vidas anteriores en donde has actuado con extrema frialdad. Has priorizado la responsabilidad y percepción social sobre la emocionalidad y el amor. Te ha llevado a vivir una existencia melancólica y en esta vida vienes a reconectar con tus emociones, a priorizar a la familia, y a mostrar comprensión incluso ante la irresponsabilidad. No vienes a conseguir logros materiales, vienes a aprender a demostrar amor. A mostrar vulnerabilidad y a encontrar seguridad no en las posesiones materiales sino en el amor del hogar y la familia. La vida te enseñará a actuar con menos frialdad, a tomar decisiones no en base a opiniones externas sino en base a tus emociones. A desarrollar intuición y a nutrir los éxitos de otros con amor, compasión y protección. En el pasado has brillado en posiciones de liderazgo a costa de otros, incluso actuando de forma dominante. Ahora descubrirás que todo éxito carece de significado si no esta sostenido por amor.`,
  'Acuario': `Vienes de vidas anteriores en donde has buscado la sabiduría, actuado con inteligencia pero también soberbia. En donde en lugar de escuchar al corazón, has utilizado la lógica y razón actuando de forma fría, impersonal e incluso aislada. En esta vida vienes a aprender a amar, a experimentar la pasión, el romance y drama. A conectar con tu voluntad, y buscar lo que quieres, no lo que es correcto, lógico o racional. Vienes a aprender a crear, a manifestar. En lugar de buscar entender cómo funcionan las cosas, aprender a modificarlas de acuerdo a tu voluntad. A convertirse en el centro de atención, no a actuar de forma extraña, rebelde o individualista. A desarrollar el poder del carisma, aun si esto implica pretender o dar importancia a las apariencias. Vienes a sentir el placentero orgullo de la vanidad y a desarrollar un sano ego que impulse tu voluntad de crear, amar y dar. Sabes mucho y tienes latente el don del liderazgo, a partir de tu apariencia, tu generosidad y voluntad disfrutaras buscar el amor de las personas y tu pareja.`,
  'Piscis': `Tiendes a ser soñadora, fantasiosa y emotiva. Pero en esta vida has venido a actuar basada en la lógica y la razón. En el pasado, tu existencia se podía considerar caótica, ibas fluyendo por donde tus emociones y las circunstancias te dictaban. Actuabas improvisadamente, sin un plan, ocasionalmente te llevó a situaciones de sufrimiento. Ahora vienes a aprender a ser organizada, actuar con precaución y en lugar de ser distraída prestar atención a los pequeños detalles. Aún teniendo una inmensa fe, no todo se lo podemos dejar a Dios. También nos toca realizar nuestro servicio y cuidar nuestros hábitos y salud. Los sueños nos inspiran, pero el trabajo en la vida diaria, la rutina, y los planes es muchas veces lo que los hace realidad. Estás acostumbrada a que las cosas te pasen mágicamente, a tener intuición de lo que va a pasar. Pero ahora te toca aprender a controlar las circunstancias y en lugar de estar a la deriva de las circunstancias, buscar las situaciones que te eviten el sufrimiento o híper sensibilidad.`
};

export function getLectureForScript(scriptId: string, user: UserProfile | null) {
  if (!user) return null;

  switch (scriptId) {
    case 'identidad':
      return {
        title: `Tu Sol en ${user.sunSign}`,
        content: SUN_LECTURES[user.sunSign] || 'No se encontró lectura para tu signo solar.'
      };
    case 'emociones':
      return {
        title: `Tu Luna en ${user.moonSign}`,
        content: MOON_LECTURES[user.moonSign] || 'No se encontró lectura para tu signo lunar.'
      };
    case 'venus':
      return {
        title: `Tu Venus en ${user.venusSign}`,
        content: VENUS_LECTURES[user.venusSign] || 'No se encontró lectura para tu signo de Venus.'
      };
    case 'infancia':
      return [
        {
          title: `Tu Casa Cuatro en ${user.casaCuatroSign || ''}`,
          content: user.casaCuatroSign ? (CASA_CUATRO_LECTURES[user.casaCuatroSign] || 'No se encontró lectura para tu Casa Cuatro.') : 'No se configuró Casa Cuatro.'
        },
        {
          title: `Tu Padre (Sol en ${user.sunSign})`,
          content: PADRE_LECTURES[user.sunSign] || 'No se encontró lectura para tu Padre.'
        },
        {
          title: `Tu Madre (Luna en ${user.moonSign})`,
          content: MADRE_LECTURES[user.moonSign] || 'No se encontró lectura para tu Madre.'
        }
      ];
    case 'descendente':
      return {
        title: `Tu Descendente en ${user.descendenteSign || ''}`,
        content: user.descendenteSign ? (DESCENDENTE_LECTURES[user.descendenteSign] || 'No se encontró lectura para tu Descendente.') : 'No se configuró Descendente.'
      };
    case 'nodo_lunar':
      return {
        title: `Tu Nodo Lunar en ${user.nodoLunarSign || ''}`,
        content: user.nodoLunarSign ? (NODO_LUNAR_LECTURES[user.nodoLunarSign] || 'No se encontró lectura para tu Nodo Lunar.') : 'No se configuró Nodo Lunar.'
      };
    default:
      return null;
  }
}
